const SYSTEM = "Jesteś copywriterem. Tworzysz 3 różne warianty reklamy/posta po polsku zgodnie z briefem, kanałem i tonem. Każdy wariant ma inny kąt (korzyść, problem, dowód).\n\nOdpowiedz WYŁĄCZNIE poprawnym obiektem JSON z polami: {\"warianty\": tablica 3 obiektów { \"naglowek\", \"tresc\", \"cta\" }}. Nie wymyślaj faktów, cen ani danych, których nie ma w treści.";
const user = `Brief: ${$json.brief}\nKanał: ${$json.kanal}\nTon: ${$json.ton}`;
return {
  json: {
    ...$json,
    _aiRequest: {
      model: ($('Konfiguracja').first().json.modelAI || "gpt-4o-mini"),
      max_tokens: 900,
      temperature: 0.3,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: SYSTEM },
        { role: 'user', content: String(user).slice(0, 12000) },
      ],
    },
  },
};

// Łączymy dane wejściowe (sprzed wywołania AI) z odpowiedzią modelu.
const ctx = { ...$('AI: prompt (3 warianty treści)').item.json };
delete ctx._aiRequest;
let out = {};
let aiError = '';
try {
  const raw = $json.choices?.[0]?.message?.content ?? '';
  out = JSON.parse(raw);
  if (!out || typeof out !== 'object' || Array.isArray(out)) throw new Error('to nie obiekt');
} catch (e) {
  aiError = 'Nie udało się odczytać odpowiedzi AI: ' + e.message;
  out = {};
}
const defaults = {"warianty":""};
for (const [k, v] of Object.entries(defaults)) if (out[k] === undefined || out[k] === null) out[k] = v;
for (const [k, v] of Object.entries(out)) if (typeof v === 'string') out[k] = v.slice(0, 4000);

return { json: { ...ctx, ...out, _aiOk: !aiError, _aiError: aiError } };
